mapper.select:
SELECT A.CMPNY_CD AS cmpnyCd, C.CMPNY_NM AS cmpnyNm, A.AUTHOR_CD AS authorCd, A.AUTHOR_NM AS authorNm, A.AUTHOR_CN AS authorCn, A.USE_FL AS useFl, DATE_FORMAT(A.CREATION_DT, '%Y-%m-%d') AS creationDt FROM CM_AUTHOR A INNER JOIN CM_CMPNY C ON C.CMPNY_CD = A.CMPNY_CD AND C.USE_FL = 'Y' WHERE A.USE_FL = 'Y'
AND A.CMPNY_CD = #{cmpnyCd}
AND A.AUTHOR_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.CMPNY_CD, A.AUTHOR_CD LIMIT #{recordCountPerPage} OFFSET #{offset}

SELECT COUNT(*) FROM CM_AUTHOR A INNER JOIN CM_CMPNY C ON C.CMPNY_CD = A.CMPNY_CD AND C.USE_FL = 'Y' WHERE A.USE_FL = 'Y'
AND A.CMPNY_CD = #{cmpnyCd}
AND A.AUTHOR_NM LIKE CONCAT('%', #{searchKeyword}, '%')

WITH RECURSIVE MENU_TREE AS ( SELECT M.CMPNY_CD AS cmpnyCd, M.MENU_ID AS menuId, M.UPPER_MENU_ID AS upperMenuId FROM CM_MENU M WHERE M.CMPNY_CD = #{cmpnyCd} AND M.MENU_ID IN
#{menuId}
UNION ALL SELECT C.CMPNY_CD AS cmpnyCd, C.MENU_ID AS menuId, C.UPPER_MENU_ID AS upperMenuId FROM CM_MENU C INNER JOIN MENU_TREE T ON C.CMPNY_CD = T.cmpnyCd AND C.MENU_ID = T.upperMenuId WHERE T.upperMenuId IS NOT NULL AND T.upperMenuId != '#' ) SELECT DISTINCT menuId FROM MENU_TREE WHERE menuId IS NOT NULL ORDER BY menuId

SELECT CAST(BASE.MBRSH_SQ AS CHAR) AS mbrshSq , BASE.USER_ID AS userId , BASE.USER_NM AS userNm , BASE.DEPT_CD AS deptCd , D.MESSAGE_CN AS deptNm FROM ( SELECT A.MBRSH_SQ , A.USER_ID , CASE WHEN #{languageCode} = 'en_US' THEN B.USER_ENG_NM ELSE B.USER_NM END AS USER_NM , A.DEPT_CD AS DEPT_CD , C.DEPT_NM_KEY , A.CMPNY_CD FROM CM_USER_ORGNZT_MBRSH A INNER JOIN CM_USER B ON A.USER_ID = B.USER_ID LEFT JOIN CM_DEPT C ON A.DEPT_CD = C.DEPT_CD AND A.CMPNY_CD = C.CMPNY_CD WHERE A.CMPNY_CD = #{companyCode} AND A.USE_FL = 'Y' ) BASE LEFT JOIN CM_MESSAGE_LANG D ON D.LANG_KEY = BASE.DEPT_NM_KEY AND D.CMPNY_CD = BASE.CMPNY_CD AND D.LANG_CODE = #{languageCode}
CONCAT(BASE.USER_ID, BASE.USER_NM) LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY BASE.USER_ID

mapper.delete:
DELETE FROM CM_AUTHOR
WHERE CMPNY_CD = #{cmpnyCd} AND AUTHOR_CD = #{authorCd}
AND AUTHOR_CD NOT IN ('AUTH_ADMIN', 'SYS_ADMIN')

DELETE FROM CM_AUTHOR_HIERSTRCT
 WHERE CMPNY_CD = #{cmpnyCd}
   AND UPPER_AUTHOR_CD = #{upperAuthorCd}
   AND LOWER_AUTHOR_CD = #{lowerAuthorCd}
